<script lang="ts">
  import {tick} from 'svelte';
  import {loadGuideline,indexGuideline,readHash,writeHash,markReady,type Guideline,type HashState} from '../../shared/data.js';
  import {project} from './model.js';
  const initial=readHash();
  let g=$state.raw<Guideline|null>(null), view=$state.raw<HashState>(initial);
  let selected=$state(1), edgeId=$state(''), search=$state(initial.view==='explore'?initial.query:'');
  $effect(()=>{ const change=()=>{view=readHash();edgeId='';};addEventListener('hashchange',change);void loadGuideline().then(x=>g=x);return()=>removeEventListener('hashchange',change); });
  const ix=$derived(g?indexGuideline(g):null), model=$derived(g?project(g):{nodes:[],edges:[]});
  const question=$derived(view.view==='trace'?g?.questions.find(q=>q.id===view.question):undefined);
  const key=$derived(view.view==='rule'?`${view.document}:${view.sentence}`:'');
  const rule=$derived(ix?.rules.get(key));
  const sentence=$derived(ix?.sentence(key));
  const matches=$derived(view.view==='explore'?model.nodes.filter(n=>`${n.number} ${n.label} ${n.terms}`.toLowerCase().includes(view.query.toLowerCase().replaceAll('-',' '))):[]);
  const traceKeys=$derived(new Set(question?.statements.map(s=>`${s.document}:${s.sentence}`)??[]));
  const active=$derived(view.view==='rule'?(ix?.docs.get(view.document)?.rec??selected):view.view==='trace'?(g?.documents.find(d=>d.id===question?.statements[0]?.document)?.rec??selected):view.view==='explore'?(matches.some(n=>n.number===selected)?selected:matches[0]?.number??0):selected);
  const focused=$derived(model.nodes.find(n=>n.number===active));
  const neighbors=$derived(model.edges.filter(e=>e.source===active||e.target===active));
  const pickedEdge=$derived(model.edges.find(e=>e.id===edgeId));
  const lit=$derived(new Set(model.edges.filter(e=>view.view==='trace'?e.rules.some(r=>traceKeys.has(r)):view.view==='rule'?e.rules.includes(key):e.source===active||e.target===active).map(e=>e.id)));
  const at=(n:number)=>{const a=-Math.PI/2+(n-1)*Math.PI/6;return{x:410+285*Math.cos(a),y:365+285*Math.sin(a)}};
  const wrap=(s:string,w=22)=>{const rows=[''];for(const word of s.split(' ')){const i=rows.length-1;if((rows[i]+' '+word).length>w&&rows[i])rows.push(word);else rows[i]=(rows[i]+' '+word).trim();}return rows;};
  function go(v:HashState){view=v;edgeId='';writeHash(v);}
  function node(n:number){selected=n;edgeId='';if(view.view!=='overview')go({view:'explore',query:`${n}`});}
  function openRule(k:string){const a=k.lastIndexOf(':');go({view:'rule',document:k.slice(0,a),sentence:Number(k.slice(a+1))});}
  $effect(()=>{view;selected;edgeId;if(g)void tick().then(markReady);});
</script>

{#snippet evidence(k:string)}
  {@const r=ix?.rules.get(k)}{@const d=r?ix?.docs.get(r.document):undefined}
  {#if r}<article class="evidence"><button class="link" onclick={()=>openRule(k)}>Recommendation {d?.rec}, sentence {r.sentence}</button>
  <p class="condition"><strong>Condition, verbatim:</strong> {r.condition??'No condition stated in this sentence.'}</p>
  {#each g?.network.edges.filter(e=>e.rule===k)??[] as e (e.id)}<p class="advice"><strong>{e.verb}</strong> {g?.network.nodes.find(n=>n.id===e.target)?.label}{e.detail?`, ${e.detail}`:''}</p>{/each}
  <details><summary>Controlled-language sentence and source</summary><p>{r.original}</p><p>{d?.source}</p><a href={`${g?.pdf}#page=${d?.page}`} target="_blank" rel="noreferrer">Open guideline page {d?.page}</a></details></article>{/if}
{/snippet}

<main>
<header><a href="#overview" onclick={()=>go({view:'overview'})}>CNL / CKC</a><span>Clinical network studies</span></header>
<div class="title"><div><h1>How recommendations connect</h1><p>Find the situations and clinical concepts that two recommendations share.</p></div><nav aria-label="Views"><button onclick={()=>go({view:'overview'})}>Guideline shape</button><button onclick={()=>g&&go({view:'trace',question:g.questions[0].id})}>Trace an answer</button><button onclick={()=>go({view:'rule',document:'cdc2022-opioid-rec01',sentence:5})}>Explain one rule</button></nav></div>
{#if g&&ix}
<form onsubmit={e=>{e.preventDefault();go({view:'explore',query:search})}}><label for="search">Explore by clinical concept</label><input id="search" bind:value={search} placeholder="Try naloxone or chronic pain"/><button>Find recommendations</button></form>
<p class="reading"><strong>A map of overlap, not a care sequence.</strong> A line means that both recommendations mention the same situation or treatment. It does not say that one causes, supports or follows the other.</p>
<div class="workspace"><section class="graph" aria-label="Recommendation network">
<div class="graph-head"><strong>{model.nodes.length} recommendations</strong><span>{model.edges.length} shared-content connections</span></div>
<svg viewBox="0 0 820 750" aria-label="Twelve recommendations joined by shared clinical content">
{#each model.edges as e (e.id)}{@const a=at(e.source)}{@const b=at(e.target)}<line x1={a.x} y1={a.y} x2={b.x} y2={b.y} class="tie" class:lit={lit.has(e.id)} class:picked={edgeId===e.id} style:stroke-width={lit.has(e.id)?1.5+Math.sqrt(e.weight):1}/><line x1={a.x} y1={a.y} x2={b.x} y2={b.y} class="hit" role="button" tabindex="0" aria-label={`Recommendations ${e.source} and ${e.target}: ${e.terms.join('; ')}`} onclick={()=>edgeId=e.id} onkeydown={ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();edgeId=e.id}}}/>{/each}
{#if pickedEdge}{@const a=at(pickedEdge.source)}{@const b=at(pickedEdge.target)}<g class="edge-label"><rect x="235" y="305" width="350" height={45+pickedEdge.terms.length*24}/><text x="410" y="333" text-anchor="middle">Shared by {pickedEdge.source} and {pickedEdge.target}</text>{#each pickedEdge.terms as term,i}<text x="410" y={359+i*24} text-anchor="middle" class="term">{term}</text>{/each}</g>{:else}<g class="center-label"><text x="410" y="350" text-anchor="middle">{view.view==='trace'?'Answer connections':'Select a recommendation'}</text><text x="410" y="377" text-anchor="middle" class="small">Then select a shared-content line.</text></g>{/if}
{#each model.nodes as n (n.id)}{@const p=at(n.number)}<g class="node" class:active={active===n.number} role="button" tabindex="0" aria-label={`Recommendation ${n.number}: ${n.label}`} onclick={()=>node(n.number)} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();node(n.number)}}}><circle cx={p.x} cy={p.y} r="29"/><text x={p.x} y={p.y+7} text-anchor="middle" class="number">{n.number}</text><text x={p.x} y={p.y+47} text-anchor="middle" class="grade">Category {n.grade?.category}, type {n.grade?.evidenceType}</text>{#each wrap(n.label,25) as line,i}<text x={p.x} y={p.y+65+i*15} text-anchor="middle" class="node-name">{line}</text>{/each}</g>{/each}
</svg>
<p class="legend">Node: recommendation with its source grade. Line width: number of distinct supporting rules. Highlighted lines belong to the selected recommendation, answer or rule.</p>
<div class="mobile-names">{#each model.nodes as n}<button onclick={()=>node(n.number)}><strong>{n.number}</strong> {n.label}</button>{/each}</div>
</section>
<aside>
{#if view.view==='trace'}<h2>Trace an answer</h2><select aria-label="Prepared question" value={question?.id} onchange={e=>go({view:'trace',question:e.currentTarget.value})}>{#each g.questions as q}<option value={q.id}>{q.question}</option>{/each}</select>{#if question}<p>The answer's statements light the connections supported by those rules. The list preserves every statement, even one with no shared-content connection.</p>{#each question.statements as s,i}<details><summary>Statement {i+1}: recommendation {ix.docs.get(s.document)?.rec}</summary>{@render evidence(`${s.document}:${s.sentence}`)}</details>{/each}{:else}<p class="notfound">Question not found. Choose a prepared question.</p>{/if}
{:else if view.view==='rule'}<h2>One rule, whole</h2>{#if sentence}<p>Recommendation {ix.docs.get(view.document)?.rec}, sentence {view.sentence}</p>{#if rule}{@render evidence(key)}{:else}<p>This sentence has no clinical parse.</p><blockquote>{sentence.ace}</blockquote>{/if}{:else}<p class="notfound">Rule not found. Select a connection or recommendation.</p>{/if}
{:else if view.view==='explore'&&matches.length===0}<h2>No recommendation found</h2><p class="notfound">No recommendation matches “{view.query}”. Try pain or opioid.</p>
{:else}<h2>Recommendation {focused?.number}</h2><p class="rec-label">{focused?.label}</p><p>Category {focused?.grade?.category} recommendation, evidence type {focused?.grade?.evidenceType}</p>{#if view.view==='explore'}<p>{matches.length} matching recommendations</p><div class="match-buttons">{#each matches as n}<button onclick={()=>selected=n.number}>{n.number}</button>{/each}</div>{/if}<details><summary>Read this recommendation</summary><p>{focused?.source}</p><a href={`${g.pdf}#page=${focused?.page}`} target="_blank" rel="noreferrer">Open guideline page {focused?.page}</a></details><h3>Neighbours and what they share</h3>{#each neighbors as e}<button class="neighbor" class:selected={edgeId===e.id} onclick={()=>edgeId=e.id}><strong>Recommendation {e.source===active?e.target:e.source}</strong><span>{e.terms.join('; ')}</span><small>{e.weight} supporting rules</small></button>{:else}<p>No shared situation or treatment under this projection.</p>{/each}{/if}
{#if pickedEdge}<section class="edge-evidence"><h2>Why {pickedEdge.source} and {pickedEdge.target} connect</h2>{#each pickedEdge.terms as t}<p>{t}</p>{/each}<p>Overlap alone does not equate the rules' conditions or recommendations.</p>{#each pickedEdge.rules as k}{@render evidence(k)}{/each}</section>{/if}
</aside></div>
<details class="table"><summary>All {model.edges.length} connections as a table</summary><div class="table-scroll"><table><thead><tr><th>Recommendations</th><th>Shared content</th><th>Supporting rules</th></tr></thead><tbody>{#each model.edges as e}<tr><td><button onclick={()=>{selected=e.source;edgeId=e.id}}> {e.source} and {e.target}</button></td><td>{e.terms.join('; ')}</td><td>{e.weight}</td></tr>{/each}</tbody></table></div></details>
<section class="boundaries"><h2>Where these recommendations stop</h2><details><summary>{g.exclusions.length} scope exclusion records</summary><p>The recommendations do not apply under these conditions. An absent exclusion does not establish that a patient belongs to the guideline population.</p>{#each g.exclusions as e}<p>{e.ace}</p>{/each}</details><details><summary>{g.supersessions.length} superseded statements</summary>{#each g.supersessions as s}<p><s>{s.ace}</s> Superseded {s.date} by <a href={s.url}>{s.citation}</a>.</p>{/each}</details></section>
<footer><p><strong>Prototype reading:</strong> Generic patient and example terms do not create overlap. This prototype identifies a treatment by these words in its acted-on label: therapy, therapies, medication, medications, opioid, opioids, benzodiazepine, benzodiazepines, depressant, depressants or naloxone. This classification is the prototype’s reading, not a KB category.</p><p>{g.derivation} Shared terms come from the clinical concept projection, whose situation anchors are a prototype reading of the rule's condition. Clinical demonstration only. Source: CDC. CDC does not endorse this demo.</p></footer>
{:else}<p>Loading the guideline…</p>{/if}
</main>

<style>
main{max-width:1480px;margin:auto;padding:24px 32px}header{display:flex;gap:20px;border-bottom:1px solid var(--border);padding-bottom:16px}header a{font-weight:750;color:var(--text);text-decoration:none}header span{color:var(--text-muted)}h1{font-size:34px;line-height:1.15;margin:24px 0 10px}h2{font-size:22px;line-height:1.25;margin:0 0 12px}h3{font-size:17px}.title{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:20px}.title p{margin:0;max-width:65ch;color:var(--text-muted)}nav{display:flex;gap:6px;flex-wrap:wrap}button,input,select{font:inherit;color:var(--text);background:var(--surface-raised);border:1px solid var(--border);padding:8px 12px;border-radius:4px}button{cursor:pointer}button:hover{border-color:var(--action)}a,.link{color:var(--action)}:global(:focus-visible){outline:3px solid var(--focus-ring);outline-offset:3px}form{display:flex;gap:12px;align-items:center;background:var(--surface-sunken);padding:12px 16px}form label{font-weight:650}input{flex:1;min-width:0}form button{background:var(--action);color:var(--action-text)}.reading{max-width:100ch;font-size:14px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:24px;align-items:start}.graph{min-width:0;background:var(--surface-raised);border:1px solid var(--border)}.graph-head{padding:12px 16px;display:flex;justify-content:space-between;font-size:13px;gap:10px}.graph-head span{color:var(--text-muted)}svg{display:block;width:100%;overflow:visible}.tie{stroke:var(--graph-edge);opacity:.12}.tie.lit{stroke:var(--action);opacity:.65}.tie.picked{stroke:var(--graph-event);opacity:1}.hit{stroke:transparent;stroke-width:14;cursor:pointer}.node{cursor:pointer}.node circle{fill:var(--graph-document);stroke:var(--surface-raised);stroke-width:3}.node.active circle{stroke:var(--text);stroke-width:5}.number{fill:var(--graph-label);font-size:23px;font-weight:750}.grade{fill:var(--text);font-size:12px;font-weight:650}.node-name{fill:var(--text);font-size:12px;paint-order:stroke;stroke:var(--surface-raised);stroke-width:4;stroke-linejoin:round}.center-label text{fill:var(--text);font-size:18px;paint-order:stroke;stroke:var(--surface-raised);stroke-width:7}.center-label .small{font-size:13px}.edge-label rect{fill:var(--surface-raised);stroke:var(--border)}.edge-label text{fill:var(--text);font-size:16px}.edge-label .term{font-size:13px}.legend{font-size:13px;color:var(--text-muted);padding:0 16px 12px}.mobile-names{display:none}aside{min-width:0;max-height:850px;overflow:auto;padding-right:8px}select{width:100%}aside p{font-size:14px}.rec-label{font-size:20px;font-weight:650}.neighbor{display:block;width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--border);border-radius:0;padding:12px 0}.neighbor span,.neighbor small{display:block}.neighbor span{font-size:14px;margin-top:4px}.neighbor small{color:var(--text-muted)}.neighbor.selected{border-left:4px solid var(--action);padding-left:10px}.evidence{padding:12px 0;border-bottom:1px solid var(--border)}.condition{border-left:3px solid var(--graph-entity);padding-left:10px;overflow-wrap:anywhere}.advice{margin:5px 0}.link{border:0;background:none;text-decoration:underline;padding:0;text-align:left}details{margin:8px 0}summary{cursor:pointer;font-weight:650;padding:7px 0}.edge-evidence{margin-top:24px;border-top:2px solid var(--action);padding-top:18px}.table{margin-top:24px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--border);padding:8px}.boundaries{max-width:90ch;margin-top:30px;border-top:1px solid var(--border);padding-top:24px}.boundaries p{font-size:14px}footer{max-width:100ch;font-size:12px;color:var(--text-muted);padding:20px 0}.notfound{border:1px solid var(--warn);padding:12px}.match-buttons{display:flex;gap:5px;flex-wrap:wrap}a{overflow-wrap:anywhere}
@media(max-width:900px){main{padding:16px}.title{display:block}nav{margin-top:16px}.workspace{grid-template-columns:minmax(0,1fr)}aside{max-height:none;overflow:visible}form{flex-wrap:wrap}form label{width:100%}h1{font-size:28px}}
@media(max-width:500px){.node-name{display:none}.grade{font-size:15px}.number{font-size:29px}.graph-head{display:block}.graph-head span{display:block}.center-label text{font-size:20px}.center-label .small{font-size:17px}.mobile-names{display:grid;padding:8px;gap:4px}.mobile-names button{text-align:left;font-size:13px;border:0;border-top:1px solid var(--border);border-radius:0}.mobile-names strong{display:inline-block;width:24px}.edge-label text{font-size:18px}.edge-label .term{font-size:17px}form button{width:100%}input{width:100%}.reading{font-size:13px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
